PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?person ?birthDate WHERE {
  VALUES ?person { dbr:Rüdiger_Kruse dbr:Jérôme_Palatsi }
  OPTIONAL { ?person dbp:birthDate ?bd1 . }
  OPTIONAL { ?person dbo:birthDate ?bd2 . }
  BIND (COALESCE(?bd1, ?bd2) AS ?birthDate)
}
LIMIT 100

